1	/**
2	 * pyint.mjs — Python `int(str)` semantics, faithfully reproduced in JavaScript.
3	 *
4	 * Exports:
5	 *   - PyValueError        : ValueError-equivalent carrying `pyType === 'ValueError'`
6	 *   - pyStrip(s)          : Python `str.strip()` (no-arg form, Unicode whitespace set)
7	 *   - isPyDecimalDigit(cp): true iff code point `cp` is Unicode category Nd
8	 *   - pyDigitValue(cp)    : numeric value 0..9 of an Nd code point
9	 *   - pyInt(s)            : full `int(str)` parse, returning an exact BigInt
10	 *
11	 * Arbitrary precision is preserved by accumulating into a BigInt
12	 * (`v = v * 10n + BigInt(d)`), matching CPython's unbounded ints.
13	 */
14	
15	import { pyRepr } from './pyrepr.mjs';
16	
17	/**
18	 * Equivalent of Python's built-in `ValueError`.
19	 * `pyType` lets higher layers format tracebacks without instanceof plumbing.
20	 */
21	export class PyValueError extends Error {
22	  constructor(message) {
23	    super(message);
24	    this.name = 'PyValueError';
25	    /** @type {string} */
26	    this.pyType = 'ValueError';
27	  }
28	}
29	
30	/**
31	 * The exact set of code points for which CPython's `str.isspace()` is true and
32	 * which therefore get removed by the no-argument `str.strip()`.
33	 *
34	 * Note the deliberate omissions: U+200B ZERO WIDTH SPACE and U+FEFF are *not*
35	 * whitespace in Python, so `int('3​')` must raise.
36	 */
37	const PY_WHITESPACE = new Set([
38	  0x09, // \t  CHARACTER TABULATION
39	  0x0a, // \n  LINE FEED
40	  0x0b, // \v  LINE TABULATION
41	  0x0c, // \f  FORM FEED
42	  0x0d, // \r  CARRIAGE RETURN
43	  0x1c, //     FILE SEPARATOR
44	  0x1d, //     GROUP SEPARATOR
45	  0x1e, //     RECORD SEPARATOR
46	  0x1f, //     UNIT SEPARATOR
47	  0x20, //     SPACE
48	  0x85, //     NEXT LINE
49	  0xa0, //     NO-BREAK SPACE
50	  0x1680, //   OGHAM SPACE MARK
51	  0x2000, //   EN QUAD .. HAIR SPACE (0x2000-0x200A)
52	  0x2001,
53	  0x2002,
54	  0x2003,
55	  0x2004,
56	  0x2005,
57	  0x2006,
58	  0x2007,
59	  0x2008,
60	  0x2009,
61	  0x200a,
62	  0x2028, //   LINE SEPARATOR
63	  0x2029, //   PARAGRAPH SEPARATOR
64	  0x202f, //   NARROW NO-BREAK SPACE
65	  0x205f, //   MEDIUM MATHEMATICAL SPACE
66	  0x3000, //   IDEOGRAPHIC SPACE
67	]);
68	
69	/**
70	 * Python `str.strip()` — remove leading and trailing Unicode whitespace.
71	 * Operates on code points so astral characters are never split.
72	 *
73	 * @param {string} s
74	 * @returns {string}
75	 */
76	export function pyStrip(s) {
77	  const cps = [...s];
78	  let start = 0;
79	  let end = cps.length;
80	  while (start < end && PY_WHITESPACE.has(cps[start].codePointAt(0))) start += 1;
81	  while (end > start && PY_WHITESPACE.has(cps[end - 1].codePointAt(0))) end -= 1;
82	  return cps.slice(start, end).join('');
83	}
84	
85	/** Memo for Nd membership tests, keyed by code point. */
86	const ndCache = new Map();
87	
88	/** Memo for Nd digit values, keyed by code point. */
89	const digitValueCache = new Map();
90	
91	const ND_RE = /\p{Nd}/u;
92	
93	/**
94	 * Is `cp` a Unicode decimal digit (general category Nd)?
95	 * This covers ASCII 0-9 plus Arabic-Indic, Devanagari, fullwidth, etc.
96	 * Superscripts like '²' are category No and are correctly excluded.
97	 *
98	 * @param {number} cp code point
99	 * @returns {boolean}
100	 */
101	export function isPyDecimalDigit(cp) {
102	  const cached = ndCache.get(cp);
103	  if (cached !== undefined) return cached;
104	  // Guard against invalid code points reaching String.fromCodePoint.
105	  let result = false;
106	  if (Number.isInteger(cp) && cp >= 0 && cp <= 0x10ffff) {
107	    result = ND_RE.test(String.fromCodePoint(cp));
108	  }
109	  ndCache.set(cp, result);
110	  return result;
111	}
112	
113	/**
114	 * Numeric value (0..9) of an Nd code point.
115	 *
116	 * Nd digits always come in contiguous runs of ten starting at that script's
117	 * ZERO, so we locate the block zero by walking backwards at most 9 steps while
118	 * the preceding code point is still Nd; the value is then the offset.
119	 *
120	 * @param {number} cp code point known to satisfy isPyDecimalDigit
121	 * @returns {number} 0-9, or -1 if `cp` is not an Nd digit
122	 */
123	export function pyDigitValue(cp) {
124	  const cached = digitValueCache.get(cp);
125	  if (cached !== undefined) return cached;
126	
127	  if (!isPyDecimalDigit(cp)) {
128	    digitValueCache.set(cp, -1);
129	    return -1;
130	  }
131	
132	  let zero = cp;
133	  for (let step = 0; step < 9; step += 1) {
134	    if (!isPyDecimalDigit(zero - 1)) break;
135	    zero -= 1;
136	  }
137	
138	  const value = cp - zero;
139	  digitValueCache.set(cp, value);
140	  return value;
141	}
142	
143	/**
144	 * Python `int(s)` with base 10.
145	 *
146	 * Grammar accepted after `str.strip()`:
147	 *     [ '+' | '-' ] digit ( '_'? digit )*
148	 * where `digit` is any Unicode Nd code point. Underscores are permitted only as
149	 * single separators *between* digits, so '_1', '1_' and '1__0' all raise.
150	 * Only ASCII '+'/'-' are signs — U+2212 MINUS SIGN is rejected.
151	 *
152	 * @param {string} s
153	 * @returns {bigint} exact value; '-0' normalizes to 0n
154	 * @throws {PyValueError} on any malformed literal
155	 */
156	export function pyInt(s) {
157	  const original = s;
158	
159	  const fail = () => {
160	    throw new PyValueError(
161	      `invalid literal for int() with base 10: ${pyRepr(original)}`,
162	    );
163	  };
164	
165	  if (typeof s !== 'string') fail();
166	
167	  // Iterate by code point, not UTF-16 unit, so astral digits work.
168	  const cps = [...pyStrip(s)];
169	  let i = 0;
170	
171	  // Optional ASCII sign.
172	  let negative = false;
173	  if (i < cps.length && (cps[i] === '+' || cps[i] === '-')) {
174	    negative = cps[i] === '-';
175	    i += 1;
176	  }
177	
178	  // At least one digit is required immediately after the sign.
179	  if (i >= cps.length) fail();
180	
181	  let value = 0n;
182	  let sawDigit = false;
183	  let prevWasUnderscore = false;
184	
185	  for (; i < cps.length; i += 1) {
186	    const ch = cps[i];
187	
188	    if (ch === '_') {
189	      // An underscore must be preceded by a digit and followed by a digit.
190	      if (!sawDigit || prevWasUnderscore) fail();
191	      prevWasUnderscore = true;
192	      continue;
193	    }
194	
195	    const d = pyDigitValue(ch.codePointAt(0));
196	    if (d < 0) fail();
197	
198	    value = value * 10n + BigInt(d);
199	    sawDigit = true;
200	    prevWasUnderscore = false;
201	  }
202	
203	  // A trailing underscore ('1_') leaves the flag set; a digitless body fails too.
204	  if (!sawDigit || prevWasUnderscore) fail();
205	
206	  // BigInt has no negative zero, but normalize explicitly for clarity.
207	  if (value === 0n) return 0n;
208	  return negative ? -value : value;
209	}
