1	/**
2	 * iterutils.mjs — a faithful JavaScript port of the two `boltons.iterutils`
3	 * helpers used by the script: `partition` and `bucketize`.
4	 *
5	 * Design notes:
6	 *  - Both helpers consume *any* iterable exactly once and never mutate it.
7	 *  - `bucketize` returns a `Map` rather than a plain object: a `Map` preserves
8	 *    first-occurrence key insertion order for arbitrary key types (booleans
9	 *    included), which is precisely what a Python `dict` does. A plain object
10	 *    would stringify the keys and lose that fidelity.
11	 *  - The default key function is `pyBool`, the Python truthiness rule, so that
12	 *    `partition(src)` / `bucketize(src)` behave like their `bool`-keyed Python
13	 *    counterparts.
14	 */
15	
16	import { PyTuple } from './pyrepr.mjs';
17	
18	/**
19	 * Python truthiness (`bool(x)`).
20	 *
21	 * Falsy: `false`, `null`/`undefined` (Python `None`), numeric zero, `0n`, the
22	 * empty string, the empty array (`[]`), and empty `Map`/`Set` (`{}` / `set()`).
23	 * Everything else is truthy — including `NaN`, which is truthy in Python even
24	 * though it is falsy under JavaScript's own coercion rules.
25	 *
26	 * @param {unknown} x
27	 * @returns {boolean}
28	 */
29	export function pyBool(x) {
30	  if (x === null || x === undefined || x === false) return false;
31	  if (x === true) return true;
32	
33	  switch (typeof x) {
34	    case 'number':
35	      return x !== 0; // NaN -> true, matching Python's float('nan')
36	    case 'bigint':
37	      return x !== 0n;
38	    case 'string':
39	      return x.length > 0;
40	    default:
41	      break;
42	  }
43	
44	  if (Array.isArray(x)) return x.length > 0; // list/tuple
45	  if (x instanceof Map || x instanceof Set) return x.size > 0; // dict/set
46	  return true; // any other object is truthy
47	}
48	
49	/**
50	 * A terse, Python-`repr`-ish rendering of a value, used only inside the
51	 * TypeError messages below. Deliberately local so this module needs nothing
52	 * from `pyrepr.mjs` beyond `PyTuple`.
53	 *
54	 * @param {unknown} value
55	 * @returns {string}
56	 */
57	function describe(value) {
58	  if (typeof value === 'string') return JSON.stringify(value);
59	  if (typeof value === 'function') return `function ${value.name || '<anonymous>'}`;
60	  if (value === null) return 'null';
61	  return `${typeof value} ${String(value)}`;
62	}
63	
64	/**
65	 * Resolve the `key` argument into a callable, mirroring boltons: a function is
66	 * used as-is, and a string is treated as an attribute/property getter that
67	 * falls back to the element itself when the property is absent (Python's
68	 * `getattr(x, key, x)`).
69	 *
70	 * @param {Function|string} key
71	 * @returns {(value: any) => any}
72	 */
73	function toKeyFunc(key) {
74	  if (typeof key === 'function') return key;
75	
76	  if (typeof key === 'string') {
77	    return (value) => {
78	      if (value === null || value === undefined) return value;
79	      const obj = Object(value); // box primitives so `in` works on them
80	      return key in obj ? obj[key] : value;
81	    };
82	  }
83	
84	  throw new TypeError(`expected callable or string, not ${describe(key)}`);
85	}
86	
87	/**
88	 * Assert that `src` can be iterated, then hand back the iterable unchanged.
89	 *
90	 * @param {Iterable<any>} src
91	 * @returns {Iterable<any>}
92	 */
93	function checkIterable(src) {
94	  if (src === null || src === undefined || typeof src[Symbol.iterator] !== 'function') {
95	    throw new TypeError(`expected an iterable src, not ${describe(src)}`);
96	  }
97	  return src;
98	}
99	
100	/**
101	 * Build the 2-tuple returned by `partition`.
102	 *
103	 * `PyTuple` is defined in a sibling module, so tolerate either reasonable
104	 * shape: a wrapper constructed from a list of items, or an `Array` subclass
105	 * (whose inherited constructor has single-argument semantics that would
106	 * otherwise nest the pair inside another array).
107	 *
108	 * @param {any[]} items
109	 * @returns {PyTuple}
110	 */
111	function makePyTuple(items) {
112	  const proto = PyTuple.prototype;
113	  if (proto instanceof Array || proto === Array.prototype) {
114	    return typeof PyTuple.from === 'function' ? PyTuple.from(items) : new PyTuple(...items);
115	  }
116	  return new PyTuple(items);
117	}
118	
119	/**
120	 * `boltons.iterutils.partition(src, key=bool)`
121	 *
122	 * Split `src` into two lists: elements whose key is truthy come first.
123	 * Relative order is preserved within each list.
124	 *
125	 *   partition([1, 2, 3, 4], x => x % 2 === 0)  ->  ([2, 4], [1, 3])
126	 *
127	 * @param {Iterable<any>} src   any iterable; it is not mutated
128	 * @param {Function|string} [key=pyBool]
129	 * @returns {PyTuple} a 2-tuple of `[trues, falses]`
130	 */
131	export function partition(src, key = pyBool) {
132	  const keyFunc = toKeyFunc(key);
133	  const trues = [];
134	  const falses = [];
135	
136	  for (const value of checkIterable(src)) {
137	    // Python-truthiness of the key result decides the bucket. (boltons routes
138	    // this through `bucketize(...).get(True)`, which works there only because
139	    // Python hashes `True` and `1` identically; a JS `Map` does not, so the
140	    // truthiness test is applied directly here.)
141	    (pyBool(keyFunc(value)) ? trues : falses).push(value);
142	  }
143	
144	  return makePyTuple([trues, falses]);
145	}
146	
147	/**
148	 * `boltons.iterutils.bucketize(src, key=bool, value_transform=None,
149	 * key_filter=None)`
150	 *
151	 * Group the elements of `src` by `key(element)`. Keys appear in the order they
152	 * are first produced and each bucket keeps the original element order, exactly
153	 * like the Python dict boltons builds.
154	 *
155	 *   bucketize([2, 1, 3], x => x % 2 === 0)  ->  Map { true => [2], false => [1, 3] }
156	 *
157	 * A `Map` compares keys with SameValueZero, so `true`/`false` (and `0`/`-0`)
158	 * collapse the same way Python's dict keys do.
159	 *
160	 * @param {Iterable<any>} src   any iterable; it is not mutated
161	 * @param {Function|string} [key=pyBool]
162	 * @param {object} [options]
163	 * @param {Function|null} [options.valueTransform] applied to each element before it is stored
164	 * @param {Function|null} [options.keyFilter] keys for which this returns falsy are dropped
165	 * @returns {Map<any, any[]>}
166	 */
167	export function bucketize(src, key = pyBool, { valueTransform = null, keyFilter = null } = {}) {
168	  const keyFunc = toKeyFunc(key);
169	
170	  if (valueTransform !== null && valueTransform !== undefined && typeof valueTransform !== 'function') {
171	    throw new TypeError(`expected callable value transform function, not ${describe(valueTransform)}`);
172	  }
173	  if (keyFilter !== null && keyFilter !== undefined && typeof keyFilter !== 'function') {
174	    throw new TypeError(`expected callable key filter function, not ${describe(keyFilter)}`);
175	  }
176	
177	  const transform = typeof valueTransform === 'function' ? valueTransform : (x) => x;
178	  const buckets = new Map();
179	
180	  for (const value of checkIterable(src)) {
181	    const bucketKey = keyFunc(value);
182	    if (keyFilter !== null && keyFilter !== undefined && !pyBool(keyFilter(bucketKey))) continue;
183	
184	    let bucket = buckets.get(bucketKey);
185	    if (bucket === undefined) {
186	      bucket = [];
187	      buckets.set(bucketKey, bucket); // first occurrence fixes the key order
188	    }
189	    bucket.push(transform(value));
190	  }
191	
192	  return buckets;
193	}
