/**
 * pyrepr.mjs — Python `repr()` / `str()` / `print()` emulation.
 *
 * Scope is deliberately narrow: only the value kinds this program produces
 * (str, int-as-BigInt, bool, None, list, tuple, dict) are supported.
 *
 * Node.js ESM, zero dependencies.
 */

/* ------------------------------------------------------------------ *
 * str.isprintable()
 * ------------------------------------------------------------------ */

/**
 * Python considers a code point non-printable when its Unicode general
 * category is one of Cc, Cf, Cs, Co, Cn (unassigned), Zl, Zp or Zs — with the
 * single exception of U+0020 SPACE, which *is* printable.
 *
 * V8's regex property escapes have no `\p{Cn}` class (unassigned code points
 * are simply absent from every category), so instead of enumerating the
 * negative set we test the positive one: a code point is printable iff it
 * belongs to one of the "visible" major categories L, M, N, P or S, or it is
 * the ASCII space.
 *
 * That single rule is exactly equivalent to Python's definition:
 *   - L/M/N/P/S are always printable;
 *   - Z other than U+0020 is non-printable (Zs/Zl/Zp all excluded here);
 *   - every C category (including unassigned Cn and lone surrogates Cs) is
 *     excluded, since none of them match L/M/N/P/S.
 */
const PRINTABLE_CATEGORY_RE = /^[\p{L}\p{M}\p{N}\p{P}\p{S}]$/u;

/** Memoised answers for the Latin-1 range, which dominates real input. */
const printableCache = new Uint8Array(0x100).fill(0xff); // 0xff = "not computed"

/**
 * Python `str.isprintable()` for a single code point.
 *
 * @param {number} cp Unicode code point (0x0 – 0x10FFFF).
 * @returns {boolean} true when the code point is printable.
 */
export function pyIsPrintable(cp) {
  if (!Number.isInteger(cp) || cp < 0 || cp > 0x10ffff) return false;

  // U+0020 SPACE is the one Zs code point Python calls printable.
  if (cp === 0x20) return true;

  if (cp < 0x100) {
    const cached = printableCache[cp];
    if (cached !== 0xff) return cached === 1;
    const result = PRINTABLE_CATEGORY_RE.test(String.fromCodePoint(cp));
    printableCache[cp] = result ? 1 : 0;
    return result;
  }

  return PRINTABLE_CATEGORY_RE.test(String.fromCodePoint(cp));
}

/* ------------------------------------------------------------------ *
 * Tuple wrapper
 * ------------------------------------------------------------------ */

/**
 * Minimal stand-in for a Python tuple, so `pyRepr` can tell `(1, 2)` apart
 * from `[1, 2]`.
 */
export class PyTuple {
  /** @param {Iterable<unknown>} [items] */
  constructor(items = []) {
    /** @type {unknown[]} */
    this.items = Array.from(items);
  }

  /** Number of elements, mirroring `len(t)`. */
  get length() {
    return this.items.length;
  }

  /** Allows `for (const x of tuple)` and spreading. */
  [Symbol.iterator]() {
    return this.items[Symbol.iterator]();
  }
}

/* ------------------------------------------------------------------ *
 * str repr
 * ------------------------------------------------------------------ */

/**
 * Escape a non-printable code point the way CPython does:
 *   cp < 0x100    -> \xNN
 *   cp < 0x10000  -> \uNNNN
 *   otherwise     -> \UNNNNNNNN
 * Hex digits are lowercase and zero padded.
 *
 * @param {number} cp
 * @returns {string}
 */
function escapeCodePoint(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * Python `repr()` of a string.
 *
 * Quote selection: single quotes by default; double quotes when the string
 * contains a `'` but no `"` (CPython never escapes the quote it can avoid).
 *
 * Escaping order matters — backslash first (so later-inserted backslashes are
 * not re-escaped), then the active quote, then the \n \r \t shorthands, then
 * anything Python calls non-printable.
 *
 * @param {string} s
 * @returns {string}
 */
function reprString(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";

  let out = quote;
  // Iterating the string (rather than its UTF-16 units) walks code points,
  // which is what CPython escapes on. Lone surrogates come through as single
  // code points and land in the non-printable branch, as they do in Python.
  for (const ch of s) {
    const cp = ch.codePointAt(0);

    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (pyIsPrintable(cp)) out += ch;
    else out += escapeCodePoint(cp);
  }
  return out + quote;
}

/* ------------------------------------------------------------------ *
 * Number rendering
 * ------------------------------------------------------------------ */

/**
 * Python-ish rendering of a plain JS number. Not on the hot path (integers in
 * this program are BigInt); it exists so debugging output stays sane.
 *
 * @param {number} n
 * @returns {string}
 */
function reprNumber(n) {
  if (Number.isNaN(n)) return 'nan';
  if (n === Infinity) return 'inf';
  if (n === -Infinity) return '-inf';
  // Integral values print like Python ints: no trailing ".0".
  if (Number.isInteger(n)) return String(n === 0 ? 0 : n);
  return String(n);
}

/* ------------------------------------------------------------------ *
 * repr / str / print
 * ------------------------------------------------------------------ */

/**
 * Python `repr()` for the value kinds this program needs.
 *
 * JS string -> str repr        BigInt  -> decimal int
 * boolean   -> True/False      null    -> None
 * Array     -> [a, b]          PyTuple -> (a, b) / () / (a,)
 * Map       -> {k: v} in insertion order (preserves bucketize key order)
 *
 * @param {unknown} value
 * @returns {string}
 */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';

  switch (typeof value) {
    case 'string':
      return reprString(value);
    case 'bigint':
      return value.toString(10);
    case 'boolean':
      return value ? 'True' : 'False';
    case 'number':
      return reprNumber(value);
  }

  if (Array.isArray(value)) {
    return '[' + value.map(pyRepr).join(', ') + ']';
  }

  if (value instanceof PyTuple) {
    const parts = value.items.map(pyRepr);
    // A 1-tuple keeps its disambiguating trailing comma: (a,)
    if (parts.length === 1) return '(' + parts[0] + ',)';
    return '(' + parts.join(', ') + ')';
  }

  if (value instanceof Map) {
    const parts = [];
    for (const [k, v] of value) parts.push(pyRepr(k) + ': ' + pyRepr(v));
    return '{' + parts.join(', ') + '}';
  }

  // Nothing else should reach here; fall back to something readable.
  return String(value);
}

/**
 * Python `str()`. Identical to `repr()` for every container (Python's
 * str of a tuple/list/dict calls repr on the object and on its members);
 * a top-level string is returned unquoted.
 *
 * @param {unknown} value
 * @returns {string}
 */
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

/**
 * Python `print()` of a single value: `str(value)` followed by a newline,
 * written to stdout.
 *
 * @param {unknown} value
 */
export function pyPrint(value) {
  process.stdout.write(pyStr(value) + '\n');
}

