1	/**
2	 * argparse.mjs — a small, faithful clone of the subset of CPython's `argparse`
3	 * that this project needs.
4	 *
5	 * The parsing core is a direct port of CPython 3.12's
6	 * `ArgumentParser._parse_known_args` / `_parse_optional` / `_get_option_tuples`
7	 * / `_match_argument`, and the help output is a port of `HelpFormatter`.
8	 * Ported faithfully so that usage strings, help layout, error wording, stderr
9	 * routing and exit codes are byte-identical to the reference implementation.
10	 *
11	 * Supported: long/short optional arguments, `--opt=value`, long-option
12	 * abbreviation (with ambiguity detection), `--` end-of-options, `type=`
13	 * conversion, `required=`, `help=`, and the `store` / `store_true` /
14	 * `store_false` / `store_const` / `count` / `help` actions.
15	 *
16	 * Deliberately NOT supported (not needed here, and left out to keep this
17	 * honest rather than half-done): positional arguments, subparsers, `nargs`,
18	 * `choices`, `metavar` inference beyond `DEST.upper()`, mutually exclusive
19	 * groups, argument groups, and `@file` argument files.
20	 *
21	 * Self-contained: no imports at all. Only `process.stdout.write`,
22	 * `process.stderr.write`, `process.argv` and `process.exit` are used.
23	 */
24	
25	// ---------------------------------------------------------------------------
26	// Constants
27	// ---------------------------------------------------------------------------
28	
29	/** Default prefix character set (CPython: `prefix_chars='-'`). */
30	const DEFAULT_PREFIX_CHARS = '-';
31	
32	/** HelpFormatter: how far each nesting level indents. */
33	const INDENT_INCREMENT = 2;
34	
35	/** HelpFormatter: hard cap on the column where help text may start. */
36	const MAX_HELP_POSITION = 24;
37	
38	/**
39	 * Terminal width assumed for wrapping. CPython uses
40	 * `shutil.get_terminal_size().columns - 2`, which falls back to 80 columns
41	 * when stdout is not a TTY (i.e. whenever output is captured). We hard-code
42	 * that fallback so output is deterministic and does not depend on the
43	 * environment the program happens to run in.
44	 */
45	const DEFAULT_COLUMNS = 80;
46	
47	/**
48	 * CPython's `argparse.SUPPRESS` sentinel. Used internally as the built-in
49	 * `-h/--help` action's `dest`, so that (exactly as in Python) `help` does not
50	 * show up as a key on the parsed namespace.
51	 */
52	const SUPPRESS = '==SUPPRESS==';
53	
54	/**
55	 * CPython's `_negative_number_matcher`, which is `^-\d+$|^-\d*\.\d+$`.
56	 *
57	 * Two details that a naive translation gets wrong:
58	 *  - Python's `\d` on `str` patterns is Unicode-aware, so `-٣` (Arabic-Indic
59	 *    digit three) matches. JavaScript's `\d` is ASCII-only, so we use
60	 *    `\p{Nd}` with the `u` flag instead.
61	 *  - Python's `$` also matches immediately before a single trailing newline,
62	 *    so `'-3\n'` matches. `\n?$` reproduces that exactly.
63	 */
64	const NEGATIVE_NUMBER_MATCHER =
65	  /^-\p{Nd}+\n?$|^-\p{Nd}*\.\p{Nd}+\n?$/u;
