71	/**
72	 * Pure-JS `os.path.basename`: split on '/' and take the last non-empty
73	 * segment. `basename('/usr/bin/prog') === 'prog'`, `basename('a/b/') === 'b'`,
74	 * `basename('/') === ''`.
75	 *
76	 * @param {string} p
77	 * @returns {string}
78	 */
79	export function basename(p) {
80	  const segments = String(p ?? '').split('/');
81	  for (let i = segments.length - 1; i >= 0; i--) {
82	    if (segments[i] !== '') return segments[i];
83	  }
84	  return '';
85	}
86	
87	/** Write to stdout. */
88	const writeStdout = (text) => process.stdout.write(text);
89	
90	/** Write to stderr. */
91	const writeStderr = (text) => process.stderr.write(text);
92	
93	/** `n` spaces — the JS equivalent of Python's `'%*s' % (n, '')`. */
94	const pad = (n) => ' '.repeat(Math.max(0, n));
95	
96	/**
97	 * Minimal single-quoted repr, used only inside argparse's own diagnostics
98	 * (`ignored explicit argument 'x'`, `invalid int value: 'x'`). This is a
99	 * deliberately tiny subset of Python's `repr()`; full repr semantics live in
100	 * the project's dedicated repr module, and importing it here would break this
101	 * module's self-containment.
102	 *
103	 * @param {string} s
104	 * @returns {string}
105	 */
106	function quote(s) {
107	  const text = String(s);
108	  const q = text.includes("'") && !text.includes('"') ? '"' : "'";
109	  const body = text
110	    .replace(/\\/g, '\\\\')
111	    .replace(new RegExp(q, 'g'), '\\' + q)
112	    .replace(/\n/g, '\\n')
113	    .replace(/\r/g, '\\r')
114	    .replace(/\t/g, '\\t');
115	  return q + body + q;
116	}
117	
118	/**
119	 * Greedy word wrap equivalent to `textwrap.wrap(text, width)` after
120	 * `re.sub(r'\s+', ' ', text).strip()` — which is what
121	 * `HelpFormatter._split_lines` does. Words longer than `width` are hard-broken,
122	 * matching textwrap's default `break_long_words=True`.
123	 *
124	 * @param {string} text
125	 * @param {number} width
126	 * @returns {string[]} the wrapped lines (empty array for blank input)
127	 */
128	function wrapText(text, width) {
129	  const words = String(text).replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
130	  const lines = [];
131	  let current = '';
132	  for (let word of words) {
133	    // Hard-break any word that cannot fit on a line of its own.
134	    while (word.length > width) {
135	      if (current !== '') {
136	        lines.push(current);
137	        current = '';
138	      }
139	      lines.push(word.slice(0, width));
140	      word = word.slice(width);
141	    }
142	    if (current === '') current = word;
143	    else if (current.length + 1 + word.length <= width) current += ' ' + word;
144	    else {
145	      lines.push(current);
146	      current = word;
147	    }
148	  }
149	  if (current !== '') lines.push(current);
150	  return lines;
151	}
