156	
157	/**
158	 * Port of `argparse.ArgumentError`: an error tied to a specific action, whose
159	 * string form is prefixed with `argument <name>: `.
160	 */
161	class ArgumentError extends Error {
162	  /**
163	   * @param {Action|null} action the offending action (null for parser-level errors)
164	   * @param {string} message
165	   */
166	  constructor(action, message) {
167	    const name = action ? getActionName(action) : null;
168	    super(name === null ? message : `argument ${name}: ${message}`);
169	    this.name = 'ArgumentError';
170	    this.argumentName = name;
171	    this.argparseMessage = message;
172	  }
173	}
174	
175	/**
176	 * Port of `argparse._get_action_name`. Note the `'/'` join: an action with
177	 * several option strings is reported as `-h/--help`.
178	 *
179	 * @param {Action} action
180	 * @returns {string|null}
181	 */
182	function getActionName(action) {
183	  if (!action) return null;
184	  if (action.option_strings.length > 0) return action.option_strings.join('/');
185	  if (action.metavar != null) return action.metavar;
186	  if (action.dest != null) return action.dest;
187	  return null;
188	}
