190	// ---------------------------------------------------------------------------
191	// Actions
192	// ---------------------------------------------------------------------------
193	
194	/**
195	 * How many argument strings each action kind consumes. `null` means "exactly
196	 * one" (CPython's `nargs=None`); `0` means "none".
197	 */
198	const NARGS_BY_KIND = {
199	  store: null,
200	  store_true: 0,
201	  store_false: 0,
202	  store_const: 0,
203	  count: 0,
204	  help: 0,
205	};
206	
207	/**
208	 * Whether an action is hidden from usage and help output. Pass `help: false`
209	 * (or the Python-style SUPPRESS string) to hide an argument.
210	 *
211	 * @param {Action} action
212	 * @returns {boolean}
213	 */
214	const isHidden = (action) => action.help === false || action.help === SUPPRESS;
215	
216	/** A single registered argument. Mirrors `argparse.Action`. */
217	class Action {
218	  /**
219	   * @param {object} spec
220	   * @param {string[]} spec.option_strings
221	   * @param {string} spec.dest
222	   * @param {string} spec.kind one of the keys of {@link NARGS_BY_KIND}
223	   * @param {((value: string) => unknown)|null} [spec.type]
224	   * @param {boolean} [spec.required]
225	   * @param {string|null} [spec.help]
226	   * @param {string|null} [spec.metavar]
227	   * @param {unknown} [spec.default]
228	   * @param {unknown} [spec.const]
229	   */
230	  constructor({
231	    option_strings,
232	    dest,
233	    kind,
234	    type = null,
235	    required = false,
236	    help = null,
237	    metavar = null,
238	    default: defaultValue,
239	    const: constValue,
240	  }) {
241	    this.option_strings = option_strings;
242	    this.dest = dest;
243	    this.kind = kind;
244	    this.nargs = NARGS_BY_KIND[kind];
245	    this.type = type;
246	    this.required = required;
247	    this.help = help;
248	    this.metavar = metavar;
249	    this.const = constValue;
250	
251	    // Defaults follow CPython: `store_true` defaults to false, and so on.
252	    if (defaultValue !== undefined) this.default = defaultValue;
253	    else if (kind === 'store_true') this.default = false;
254	    else if (kind === 'store_false') this.default = true;
255	    else if (kind === 'count') this.default = null;
256	    else this.default = null;
257	  }
258	
259	  /** The metavar shown in usage/help for this action. */
260	  get displayMetavar() {
261	    return this.metavar ?? this.dest.toUpperCase();
262	  }
263	
264	  /**
265	   * Perform the action. Mirrors `Action.__call__`.
266	   *
267	   * @param {ArgumentParser} parser
268	   * @param {Record<string, unknown>} namespace
269	   * @param {unknown} values
270	   */
271	  call(parser, namespace, values) {
272	    switch (this.kind) {
273	      case 'store':
274	        namespace[this.dest] = values;
275	        break;
276	      case 'store_true':
277	        namespace[this.dest] = true;
278	        break;
279	      case 'store_false':
280	        namespace[this.dest] = false;
281	        break;
282	      case 'store_const':
283	        namespace[this.dest] = this.const;
284	        break;
285	      case 'count':
286	        namespace[this.dest] = (namespace[this.dest] ?? 0) + 1;
287	        break;
288	      case 'help':
289	        parser.print_help();
290	        parser.exit(0);
291	        break;
292	      /* c8 ignore next 2 */
293	      default:
294	        throw new Error(`unsupported action: ${this.kind}`);
295	    }
296	  }
297	}
