300	// Help formatting
301	// ---------------------------------------------------------------------------
302	
303	/** Port of the parts of `argparse.HelpFormatter` that we need. */
304	class HelpFormatter {
305	  /**
306	   * @param {string} prog program name shown in usage
307	   * @param {number} columns assumed terminal width
308	   */
309	  constructor(prog, columns) {
310	    this.prog = prog;
311	    // CPython: `width = shutil.get_terminal_size().columns - 2`.
312	    this.width = Math.max(columns - 2, 11);
313	    this.maxHelpPosition = Math.min(
314	      MAX_HELP_POSITION,
315	      Math.max(this.width - 20, INDENT_INCREMENT * 2),
316	    );
317	  }
318	
319	  /**
320	   * `_format_action_invocation`: `-h, --help` for zero-arg actions,
321	   * `--a A` (repeated per option string) for value-taking ones.
322	   *
323	   * @param {Action} action
324	   * @returns {string}
325	   */
326	  formatInvocation(action) {
327	    if (action.nargs === 0) return action.option_strings.join(', ');
328	    const metavar = action.displayMetavar;
329	    return action.option_strings.map((opt) => `${opt} ${metavar}`).join(', ');
330	  }
331	
332	  /**
333	   * `_format_actions_usage` for a single optional: `[-h]`, `--a A`.
334	   *
335	   * @param {Action} action
336	   * @returns {string}
337	   */
338	  formatUsagePart(action) {
339	    const optionString = action.option_strings[0];
340	    const part =
341	      action.nargs === 0 ? optionString : `${optionString} ${action.displayMetavar}`;
342	    return action.required ? part : `[${part}]`;
343	  }
344	
345	  /**
346	   * The usage line(s), without a trailing newline. Port of `_format_usage`,
347	   * including the continuation-line wrapping that kicks in once the usage
348	   * exceeds the available width.
349	   *
350	   * @param {Action[]} actions
351	   * @returns {string}
352	   */
353	  formatUsage(actions) {
354	    const prefix = 'usage: ';
355	    const prog = this.prog;
356	    const visible = actions.filter((action) => !isHidden(action));
357	
358	    const optUsage = visible.map((action) => this.formatUsagePart(action)).join(' ');
359	    let usage = [prog, optUsage].filter((s) => s !== '').join(' ');
360	
361	    const textWidth = this.width;
362	    if (prefix.length + usage.length > textWidth) {
363	      // Break the usage into wrappable parts: bracketed/parenthesised groups
364	      // stay intact, everything else splits on whitespace.
365	      const optParts = optUsage.match(/\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g) ?? [];
366	
367	      /**
368	       * @param {string[]} parts
369	       * @param {string} indent
370	       * @param {string|null} [linePrefix] set on the first line only
371	       * @returns {string[]}
372	       */
373	      const getLines = (parts, indent, linePrefix = null) => {
374	        const lines = [];
375	        let line = [];
376	        let lineLen = (linePrefix !== null ? linePrefix.length : indent.length) - 1;
377	        for (const part of parts) {
378	          if (lineLen + 1 + part.length > textWidth && line.length > 0) {
379	            lines.push(indent + line.join(' '));
380	            line = [];
381	            lineLen = indent.length - 1;
382	          }
383	          line.push(part);
384	          lineLen += 1 + part.length;
385	        }
386	        if (line.length > 0) lines.push(indent + line.join(' '));
387	        if (linePrefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
388	        return lines;
389	      };
390	
391	      let lines;
392	      if (prefix.length + prog.length <= 0.75 * textWidth) {
393	        // Short program name: the first group of options follows it.
394	        const indent = pad(prefix.length + prog.length + 1);
395	        lines = optParts.length > 0 ? getLines([prog, ...optParts], indent, prefix) : [prog];
396	      } else {
397	        // Long program name: it gets a line of its own.
398	        const indent = pad(prefix.length);
399	        lines = [prog, ...getLines(optParts, indent)];
400	      }
401	      usage = lines.join('\n');
402	    }
403	
404	    return prefix + usage;
405	  }
406	
407	  /**
408	   * `_action_max_length`: the longest invocation, plus the section indent.
409	   *
410	   * @param {Action[]} actions
411	   * @returns {number}
412	   */
413	  actionMaxLength(actions) {
414	    let max = 0;
415	    for (const action of actions) {
416	      if (isHidden(action)) continue;
417	      max = Math.max(max, this.formatInvocation(action).length + INDENT_INCREMENT);
418	    }
419	    return max;
420	  }
421	
422	  /**
423	   * `_format_action`: one entry of the `options:` section, including the
424	   * column alignment and help-text wrapping.
425	   *
426	   * @param {Action} action
427	   * @param {number} helpPosition column at which help text starts
428	   * @returns {string}
429	   */
430	  formatAction(action, helpPosition) {
431	    const helpWidth = Math.max(this.width - helpPosition, 11);
432	    const actionWidth = helpPosition - INDENT_INCREMENT - 2;
433	    const invocation = this.formatInvocation(action);
434	
435	    let header;
436	    let indentFirst = 0;
437	    const helpText = action.help ? String(action.help) : '';
438	
439	    if (!helpText) {
440	      // No help: the invocation is the whole line.
441	      header = pad(INDENT_INCREMENT) + invocation + '\n';
442	    } else if (invocation.length <= actionWidth) {
443	      // Short invocation: pad it out so help starts at `helpPosition`.
444	      header = pad(INDENT_INCREMENT) + invocation + pad(actionWidth - invocation.length) + '  ';
445	      indentFirst = 0;
446	    } else {
447	      // Long invocation: help starts on the following line.
448	      header = pad(INDENT_INCREMENT) + invocation + '\n';
449	      indentFirst = helpPosition;
450	    }
451	
452	    const parts = [header];
453	    if (helpText.trim() !== '') {
454	      const lines = wrapText(helpText, helpWidth);
455	      parts.push(pad(indentFirst) + lines[0] + '\n');
456	      for (const line of lines.slice(1)) parts.push(pad(helpPosition) + line + '\n');
457	    } else if (!header.endsWith('\n')) {
458	      parts.push('\n');
459	    }
460	    return parts.join('');
461	  }
462	
463	  /**
464	   * The complete help text, matching `ArgumentParser.format_help()` byte for
465	   * byte (including the blank-line collapsing and single trailing newline).
466	   *
467	   * @param {Action[]} actions
468	   * @param {{description?: string|null, epilog?: string|null}} [text]
469	   * @returns {string}
470	   */
471	  formatHelp(actions, { description = null, epilog = null } = {}) {
472	    const parts = [this.formatUsage(actions) + '\n\n'];
473	
474	    if (description) parts.push(wrapText(description, this.width).join('\n') + '\n\n');
475	
476	    const visible = actions.filter((action) => !isHidden(action));
477	    if (visible.length > 0) {
478	      const helpPosition = Math.min(this.actionMaxLength(visible) + 2, this.maxHelpPosition);
479	      parts.push('\n', 'options:\n');
480	      for (const action of visible) parts.push(this.formatAction(action, helpPosition));
481	      parts.push('\n');
482	    }
483	
484	    if (epilog) parts.push('\n' + wrapText(epilog, this.width).join('\n') + '\n\n');
485	
486	    // `_long_break_matcher.sub('\n\n', ...)` then `.strip('\n') + '\n'`.
487	    const joined = parts.join('').replace(/\n{3,}/g, '\n\n');
488	    return joined.replace(/^\n+/, '').replace(/\n+$/, '') + '\n';
489	  }
490	}
