493	// ArgumentParser
494	// ---------------------------------------------------------------------------
495	
496	/**
497	 * A drop-in-ish clone of `argparse.ArgumentParser` for optional arguments.
498	 *
499	 * @example
500	 * const parser = new ArgumentParser();
501	 * parser.add_argument('--a', { type: String, required: true, help: 'Numbers' });
502	 * const args = parser.parse_args();   // -> { help: null, a: '1,2,3' }
503	 */
504	export class ArgumentParser {
505	  /**
506	   * @param {object} [options]
507	   * @param {string} [options.prog] program name; defaults to `basename(process.argv[1])`
508	   * @param {string|null} [options.description]
509	   * @param {string|null} [options.epilog]
510	   * @param {boolean} [options.add_help] add `-h/--help` (default true)
511	   * @param {boolean} [options.allow_abbrev] allow long-option prefixes (default true)
512	   * @param {string} [options.prefix_chars] default `'-'`
513	   * @param {boolean} [options.exit_on_error] convert ArgumentError into `error()` (default true)
514	   * @param {number} [options.columns] assumed terminal width (default 80)
515	   */
516	  constructor({
517	    prog,
518	    description = null,
519	    epilog = null,
520	    add_help = true,
521	    allow_abbrev = true,
522	    prefix_chars = DEFAULT_PREFIX_CHARS,
523	    exit_on_error = true,
524	    columns = DEFAULT_COLUMNS,
525	  } = {}) {
526	    // Python uses `basename(sys.argv[0])`; the Node equivalent is argv[1],
527	    // since argv[0] is the node binary itself.
528	    this.prog = prog ?? basename(process.argv[1] ?? '');
529	    this.description = description;
530	    this.epilog = epilog;
531	    this.prefix_chars = prefix_chars;
532	    this.allow_abbrev = allow_abbrev;
533	    this.exit_on_error = exit_on_error;
534	    this.columns = columns;
535	
536	    /** @type {Action[]} */
537	    this._actions = [];
538	    /** @type {Map<string, Action>} */
539	    this._option_string_actions = new Map();
540	    /** Set when any option string itself looks like a negative number. */
541	    this._has_negative_number_optionals = false;
542	
543	    if (add_help) {
544	      this.add_argument('-h', '--help', {
545	        action: 'help',
546	        dest: SUPPRESS, // keeps `help` off the parsed namespace, as in Python
547	        help: 'show this help message and exit',
548	      });
549	    }
550	  }
551	
552	  // -- registration --------------------------------------------------------
553	
554	  /**
555	   * Register an optional argument.
556	   *
557	   * @param {...(string|object)} args one or more flag strings, optionally
558	   *   followed by an options object:
559	   *   `{ type, required, help, action, dest, metavar, default, const }`.
560	   * @returns {Action} the created action
561	   */
562	  add_argument(...args) {
563	    let options = {};
564	    if (args.length > 0 && typeof args[args.length - 1] === 'object' && args[args.length - 1] !== null) {
565	      options = /** @type {object} */ (args.pop());
566	    }
567	    const flags = /** @type {string[]} */ (args);
568	
569	    if (flags.length === 0) {
570	      throw new Error('add_argument() requires at least one option string');
571	    }
572	    for (const flag of flags) {
573	      if (typeof flag !== 'string' || flag.length === 0 || !this.prefix_chars.includes(flag[0])) {
574	        throw new Error(
575	          `add_argument(): positional arguments are not supported (got ${quote(String(flag))})`,
576	        );
577	      }
578	    }
579	
580	    const kind = options.action ?? 'store';
581	    if (!(kind in NARGS_BY_KIND)) {
582	      throw new Error(`unsupported action: ${quote(String(kind))}`);
583	    }
584	
585	    // dest inference: prefer the first long option ('--foo-bar' -> 'foo_bar').
586	    const isLong = (flag) => flag.length > 1 && this.prefix_chars.includes(flag[1]);
587	    let dest = options.dest;
588	    if (dest == null) {
589	      const source = flags.find(isLong) ?? flags[0];
590	      dest = source.replace(new RegExp(`^[${this.prefix_chars}]+`), '').replace(/-/g, '_');
591	      if (dest === '') throw new Error(`dest is required for options like ${quote(flags[0])}`);
592	    }
593	
594	    const action = new Action({
595	      option_strings: flags,
596	      dest,
597	      kind,
598	      type: options.type ?? null,
599	      required: Boolean(options.required),
600	      help: options.help ?? null,
601	      metavar: options.metavar ?? null,
602	      default: options.default,
603	      const: options.const,
604	    });
605	
606	    for (const flag of flags) {
607	      if (this._option_string_actions.has(flag)) {
608	        throw new Error(`conflicting option string: ${flag}`);
609	      }
610	      this._option_string_actions.set(flag, action);
611	      if (NEGATIVE_NUMBER_MATCHER.test(flag)) this._has_negative_number_optionals = true;
612	    }
613	    this._actions.push(action);
614	    return action;
615	  }
616	
617	  // -- output --------------------------------------------------------------
618	
619	  /** @returns {string} the usage line, with a trailing newline. */
620	  format_usage() {
621	    return this._formatter().formatUsage(this._actions) + '\n';
622	  }
623	
624	  /** @returns {string} the full help text, with a trailing newline. */
625	  format_help() {
626	    return this._formatter()
627	      .formatHelp(this._actions, { description: this.description, epilog: this.epilog });
628	  }
629	
630	  /**
631	   * @param {(text: string) => unknown} [write] defaults to stdout
632	   */
633	  print_usage(write = writeStdout) {
634	    write(this.format_usage());
635	  }
636	
637	  /**
638	   * @param {(text: string) => unknown} [write] defaults to stdout
639	   */
640	  print_help(write = writeStdout) {
641	    write(this.format_help());
642	  }
643	
644	  /**
645	   * Print usage plus `<prog>: error: <message>` to stderr and exit with 2.
646	   *
647	   * @param {string} message
648	   * @returns {never}
649	   */
650	  error(message) {
651	    this.print_usage(writeStderr);
652	    this.exit(2, `${this.prog}: error: ${message}\n`);
653	  }
654	
655	  /**
656	   * @param {number} [status]
657	   * @param {string} [message] written to stderr when present
658	   * @returns {never}
659	   */
660	  exit(status = 0, message) {
661	    if (message) writeStderr(message);
662	    process.exit(status);
663	    /* c8 ignore next 2 */
664	    throw new Error('unreachable'); // keeps control-flow analysis honest
665	  }
666	
667	  /** @returns {HelpFormatter} */
668	  _formatter() {
669	    return new HelpFormatter(this.prog, this.columns);
670	  }
671	
672	  // -- parsing -------------------------------------------------------------
673	
674	  /**
675	   * Parse `argv`, erroring out on anything left over.
676	   *
677	   * @param {string[]} [argv] defaults to `process.argv.slice(2)`
678	   * @returns {Record<string, unknown>} the populated namespace
679	   */
680	  parse_args(argv) {
681	    const [namespace, extras] = this.parse_known_args(argv);
682	    if (extras.length > 0) {
683	      this.error(`unrecognized arguments: ${extras.join(' ')}`);
684	    }
685	    return namespace;
686	  }
687	
688	  /**
689	   * Parse `argv`, returning the namespace and any unrecognized arguments.
690	   *
691	   * @param {string[]} [argv] defaults to `process.argv.slice(2)`
692	   * @returns {[Record<string, unknown>, string[]]}
693	   */
694	  parse_known_args(argv) {
695	    const argStrings = argv ?? process.argv.slice(2);
696	
697	    // Seed defaults before parsing, as CPython does. Actions whose dest is
698	    // suppressed (the built-in --help) never appear on the namespace.
699	    /** @type {Record<string, unknown>} */
700	    const namespace = {};
701	    for (const action of this._actions) {
702	      if (action.dest === SUPPRESS) continue;
703	      if (!(action.dest in namespace)) namespace[action.dest] = action.default;
704	    }
705	
706	    try {
707	      return this._parseKnownArgs(argStrings, namespace);
708	    } catch (err) {
709	      if (this.exit_on_error && err instanceof ArgumentError) this.error(err.message);
710	      throw err;
711	    }
712	  }
713	
714	  /**
715	   * Port of `_parse_known_args`.
716	   *
717	   * @param {string[]} argStrings
718	   * @param {Record<string, unknown>} namespace
719	   * @returns {[Record<string, unknown>, string[]]}
720	   */
721	  _parseKnownArgs(argStrings, namespace) {
722	    /**
723	     * Classify every token: 'O' for an option, 'A' for a value, '-' for the
724	     * end-of-options marker. Everything after the FIRST '--' is forced to 'A'.
725	     * @type {Map<number, [Action|null, string, string|null, string|null]>}
726	     */
727	    const optionStringIndices = new Map();
728	    const patternParts = [];
729	    let sawDoubleDash = false;
730	    for (let i = 0; i < argStrings.length; i++) {
731	      const argString = argStrings[i];
732	      if (sawDoubleDash) {
733	        patternParts.push('A');
734	      } else if (argString === '--') {
735	        sawDoubleDash = true;
736	        patternParts.push('-');
737	      } else {
738	        const optionTuple = this._parseOptional(argString);
739	        if (optionTuple === null) {
740	          patternParts.push('A');
741	        } else {
742	          optionStringIndices.set(i, optionTuple);
743	          patternParts.push('O');
744	        }
745	      }
746	    }
747	    const argStringsPattern = patternParts.join('');
748	
749	    /** @type {string[]} */
750	    const extras = [];
751	    const seenActions = new Set();
752	
753	    const takeAction = (action, argumentStrings) => {
754	      seenActions.add(action);
755	      action.call(this, namespace, this._getValues(action, argumentStrings));
756	    };
757	
758	    /**
759	     * Port of `consume_optional`: handles `--opt value`, `--opt=value`, and
760	     * bundled short options such as `-xvf`.
761	     *
762	     * @param {number} startIndex
763	     * @returns {number} the index just past this option and its arguments
764	     */
765	    const consumeOptional = (startIndex) => {
766	      let [action, optionString, sep, explicitArg] = optionStringIndices.get(startIndex);
767	      /** @type {[Action, string[]][]} */
768	      const actionTuples = [];
769	      let stop;
770	
771	      for (;;) {
772	        // An unknown option string: record it as an extra and move on.
773	        if (action === null) {
774	          extras.push(argStrings[startIndex]);
775	          return startIndex + 1;
776	        }
777	
778	        if (explicitArg !== null) {
779	          const argCount = this._matchArgument(action, 'A');
780	          const chars = this.prefix_chars;
781	
782	          if (argCount === 0 && !chars.includes(optionString[1]) && explicitArg !== '') {
783	            // `-xvf`: a zero-arg short option with more short options glued on.
784	            if (sep || chars.includes(explicitArg[0])) {
785	              throw new ArgumentError(action, `ignored explicit argument ${quote(explicitArg)}`);
786	            }
787	            actionTuples.push([action, []]);
788	            const char = optionString[0];
789	            optionString = char + explicitArg[0];
790	            if (this._option_string_actions.has(optionString)) {
791	              action = this._option_string_actions.get(optionString);
792	              explicitArg = explicitArg.slice(1);
793	              if (explicitArg === '') {
794	                sep = null;
795	                explicitArg = null;
796	              } else if (explicitArg[0] === '=') {
797	                sep = '=';
798	                explicitArg = explicitArg.slice(1);
799	              } else {
800	                sep = '';
801	              }
802	            } else {
803	              extras.push(char + explicitArg);
804	              stop = startIndex + 1;
805	              break;
806	            }
807	          } else if (argCount === 1) {
808	            stop = startIndex + 1;
809	            actionTuples.push([action, [explicitArg]]);
810	            break;
811	          } else {
812	            throw new ArgumentError(action, `ignored explicit argument ${quote(explicitArg)}`);
813	          }
814	        } else {
815	          // No explicit argument: take values from the following tokens.
816	          const start = startIndex + 1;
817	          const argCount = this._matchArgument(action, argStringsPattern.slice(start));
818	          stop = start + argCount;
819	          actionTuples.push([action, argStrings.slice(start, stop)]);
820	          break;
821	        }
822	      }
823	
824	      for (const [tupleAction, tupleArgs] of actionTuples) takeAction(tupleAction, tupleArgs);
825	      return stop;
826	    };
827	
828	    /**
829	     * Port of `consume_positionals`. This parser registers no positionals, so
830	     * nothing is ever consumed; the function is kept so that the surrounding
831	     * control flow (and therefore the "unrecognized arguments" behaviour)
832	     * stays identical to CPython's.
833	     *
834	     * @param {number} startIndex
835	     * @returns {number}
836	     */
837	    const consumePositionals = (startIndex) => startIndex;
838	
839	    // Alternate between positionals and optionals until past the last option.
840	    let startIndex = 0;
841	    const optionIndices = [...optionStringIndices.keys()];
842	    const maxOptionStringIndex = optionIndices.length > 0 ? Math.max(...optionIndices) : -1;
843	
844	    while (startIndex <= maxOptionStringIndex) {
845	      const nextOptionStringIndex = Math.min(
846	        ...optionIndices.filter((index) => index >= startIndex),
847	      );
848	
849	      if (startIndex !== nextOptionStringIndex) {
850	        const positionalsEndIndex = consumePositionals(startIndex);
851	        if (positionalsEndIndex > startIndex) {
852	          startIndex = positionalsEndIndex;
853	          continue;
854	        }
855	        startIndex = positionalsEndIndex;
856	      }
857	
858	      if (!optionStringIndices.has(startIndex)) {
859	        extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
860	        startIndex = nextOptionStringIndex;
861	      }
862	
863	      startIndex = consumeOptional(startIndex);
864	    }
865	
866	    const stopIndex = consumePositionals(startIndex);
867	    extras.push(...argStrings.slice(stopIndex));
868	
869	    // Required-argument checking happens here, i.e. BEFORE parse_args()
870	    // reports unrecognized arguments.
871	    const requiredActions = [];
872	    for (const action of this._actions) {
873	      if (!seenActions.has(action) && action.required) {
874	        requiredActions.push(getActionName(action));
875	      }
876	    }
877	    if (requiredActions.length > 0) {
878	      this.error(`the following arguments are required: ${requiredActions.join(', ')}`);
879	    }
880	
881	    return [namespace, extras];
882	  }
883	
884	  /**
885	   * Port of `_parse_optional`. Returns `null` when the token is a value, or a
886	   * `[action, optionString, sep, explicitArg]` tuple when it is (or looks
887	   * like) an option. `action` is `null` for an unrecognized option string.
888	   *
889	   * @param {string} argString
890	   * @returns {[Action|null, string, string|null, string|null]|null}
891	   */
892	  _parseOptional(argString) {
893	    // Empty string, or no prefix char: it is a value.
894	    if (argString === '') return null;
895	    if (!this.prefix_chars.includes(argString[0])) return null;
896	
897	    // Exact match against a known option string.
898	    if (this._option_string_actions.has(argString)) {
899	      return [this._option_string_actions.get(argString), argString, null, null];
900	    }
901	
902	    // A bare '-' is a value.
903	    if (argString.length === 1) return null;
904	
905	    // '--opt=value' where '--opt' is known.
906	    const eq = argString.indexOf('=');
907	    if (eq !== -1) {
908	      const optionString = argString.slice(0, eq);
909	      const explicitArg = argString.slice(eq + 1);
910	      if (this._option_string_actions.has(optionString)) {
911	        return [this._option_string_actions.get(optionString), optionString, '=', explicitArg];
912	      }
913	    }
914	
915	    // Prefix/abbreviation matching.
916	    const optionTuples = this._getOptionTuples(argString);
917	    if (optionTuples.length > 1) {
918	      const matches = optionTuples.map(([, optionString]) => optionString).join(', ');
919	      this.error(`ambiguous option: ${argString} could match ${matches}`);
920	    } else if (optionTuples.length === 1) {
921	      return optionTuples[0];
922	    }
923	
924	    // Looks like a negative number, and no option string does: it is a value.
925	    if (NEGATIVE_NUMBER_MATCHER.test(argString) && !this._has_negative_number_optionals) {
926	      return null;
927	    }
928	
929	    // Contains a space: it is a value.
930	    if (argString.includes(' ')) return null;
931	
932	    // An option string, but not one this parser knows about.
933	    return [null, argString, null, null];
934	  }
935	
936	  /**
937	   * Port of `_get_option_tuples`: candidate interpretations of an abbreviated
938	   * or glued-together option string.
939	   *
940	   * @param {string} optionString
941	   * @returns {[Action, string, string|null, string|null][]}
942	   */
943	  _getOptionTuples(optionString) {
944	    /** @type {[Action, string, string|null, string|null][]} */
945	    const result = [];
946	    const chars = this.prefix_chars;
947	
948	    if (chars.includes(optionString[0]) && chars.includes(optionString[1])) {
949	      // Long option: only ever split at '='.
950	      if (!this.allow_abbrev) return result;
951	      const eq = optionString.indexOf('=');
952	      const optionPrefix = eq === -1 ? optionString : optionString.slice(0, eq);
953	      const sep = eq === -1 ? null : '=';
954	      const explicitArg = eq === -1 ? null : optionString.slice(eq + 1);
955	      for (const [known, action] of this._option_string_actions) {
956	        if (known.startsWith(optionPrefix)) result.push([action, known, sep, explicitArg]);
957	      }
958	    } else {
959	      // Short option: its argument may be glued directly to it.
960	      const optionPrefix = optionString;
961	      const shortOptionPrefix = optionString.slice(0, 2);
962	      const shortExplicitArg = optionString.slice(2);
963	      for (const [known, action] of this._option_string_actions) {
964	        if (known === shortOptionPrefix) result.push([action, known, '', shortExplicitArg]);
965	        else if (known.startsWith(optionPrefix)) result.push([action, known, null, null]);
966	      }
967	    }
968	    return result;
969	  }
970	
971	  /**
972	   * Port of `_match_argument`: how many of the following tokens this action
973	   * takes, given the classification pattern of the remaining tokens.
974	   *
975	   * @param {Action} action
976	   * @param {string} argStringsPattern
977	   * @returns {number}
978	   */
979	  _matchArgument(action, argStringsPattern) {
980	    const match = new RegExp('^' + this._nargsPattern(action)).exec(argStringsPattern);
981	    if (match === null) throw new ArgumentError(action, 'expected one argument');
982	    return match[1].length;
983	  }
984	
985	  /**
986	   * Port of `_get_nargs_pattern`. `'--'` (pattern char `-`) is never allowed
987	   * to satisfy an optional's arguments, which is why `-*` is stripped.
988	   *
989	   * @param {Action} action
990	   * @returns {string}
991	   */
992	  _nargsPattern(action) {
993	    let pattern;
994	    if (action.nargs === null) pattern = '(-*A-*)';
995	    else pattern = '(-*' + Array(action.nargs).fill('A').join('-*') + '-*)';
996	    if (action.option_strings.length > 0) {
997	      pattern = pattern.replace(/-\*/g, '').replace(/-/g, '');
998	    }
999	    return pattern;
1000	  }
1001	
1002	  /**
1003	   * Port of `_get_values` + `_get_value` for the nargs we support.
1004	   *
1005	   * @param {Action} action
1006	   * @param {string[]} argStrings
1007	   * @returns {unknown}
1008	   */
1009	  _getValues(action, argStrings) {
1010	    if (action.nargs === 0) return undefined;
1011	    const argString = argStrings[0];
1012	    if (action.type == null || action.type === String) return argString;
1013	    try {
1014	      return action.type(argString);
1015	    } catch {
1016	      const typeName = action.type.name || 'value';
1017	      throw new ArgumentError(action, `invalid ${typeName} value: ${quote(argString)}`);
1018	    }
1019	  }
1020	}
