/**
 * argparse.mjs — a small, faithful clone of the subset of CPython's `argparse`
 * that this project needs.
 *
 * The parsing core is a direct port of CPython 3.12's
 * `ArgumentParser._parse_known_args` / `_parse_optional` / `_get_option_tuples`
 * / `_match_argument`, and the help output is a port of `HelpFormatter`.
 * Ported faithfully so that usage strings, help layout, error wording, stderr
 * routing and exit codes are byte-identical to the reference implementation.
 *
 * Supported: long/short optional arguments, `--opt=value`, long-option
 * abbreviation (with ambiguity detection), `--` end-of-options, `type=`
 * conversion, `required=`, `help=`, and the `store` / `store_true` /
 * `store_false` / `store_const` / `count` / `help` actions.
 *
 * Deliberately NOT supported (not needed here, and left out to keep this
 * honest rather than half-done): positional arguments, subparsers, `nargs`,
 * `choices`, `metavar` inference beyond `DEST.upper()`, mutually exclusive
 * groups, argument groups, and `@file` argument files.
 *
 * Self-contained: no imports at all. Only `process.stdout.write`,
 * `process.stderr.write`, `process.argv` and `process.exit` are used.
 */

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Default prefix character set (CPython: `prefix_chars='-'`). */
const DEFAULT_PREFIX_CHARS = '-';

/** HelpFormatter: how far each nesting level indents. */
const INDENT_INCREMENT = 2;

/** HelpFormatter: hard cap on the column where help text may start. */
const MAX_HELP_POSITION = 24;

/**
 * Terminal width assumed for wrapping. CPython uses
 * `shutil.get_terminal_size().columns - 2`, which falls back to 80 columns
 * when stdout is not a TTY (i.e. whenever output is captured). We hard-code
 * that fallback so output is deterministic and does not depend on the
 * environment the program happens to run in.
 */
const DEFAULT_COLUMNS = 80;

/**
 * CPython's `argparse.SUPPRESS` sentinel. Used internally as the built-in
 * `-h/--help` action's `dest`, so that (exactly as in Python) `help` does not
 * show up as a key on the parsed namespace.
 */
const SUPPRESS = '==SUPPRESS==';

/**
 * CPython's `_negative_number_matcher`, which is `^-\d+$|^-\d*\.\d+$`.
 *
 * Two details that a naive translation gets wrong:
 *  - Python's `\d` on `str` patterns is Unicode-aware, so `-٣` (Arabic-Indic
 *    digit three) matches. JavaScript's `\d` is ASCII-only, so we use
 *    `\p{Nd}` with the `u` flag instead.
 *  - Python's `$` also matches immediately before a single trailing newline,
 *    so `'-3\n'` matches. `\n?$` reproduces that exactly.
 */
const NEGATIVE_NUMBER_MATCHER =
  /^-\p{Nd}+\n?$|^-\p{Nd}*\.\p{Nd}+\n?$/u;

// ---------------------------------------------------------------------------
// Small helpers
// ---------------------------------------------------------------------------

/**
 * Pure-JS `os.path.basename`: split on '/' and take the last non-empty
 * segment. `basename('/usr/bin/prog') === 'prog'`, `basename('a/b/') === 'b'`,
 * `basename('/') === ''`.
 *
 * @param {string} p
 * @returns {string}
 */
export function basename(p) {
  const segments = String(p ?? '').split('/');
  for (let i = segments.length - 1; i >= 0; i--) {
    if (segments[i] !== '') return segments[i];
  }
  return '';
}

/** Write to stdout. */
const writeStdout = (text) => process.stdout.write(text);

/** Write to stderr. */
const writeStderr = (text) => process.stderr.write(text);

/** `n` spaces — the JS equivalent of Python's `'%*s' % (n, '')`. */
const pad = (n) => ' '.repeat(Math.max(0, n));

/**
 * Minimal single-quoted repr, used only inside argparse's own diagnostics
 * (`ignored explicit argument 'x'`, `invalid int value: 'x'`). This is a
 * deliberately tiny subset of Python's `repr()`; full repr semantics live in
 * the project's dedicated repr module, and importing it here would break this
 * module's self-containment.
 *
 * @param {string} s
 * @returns {string}
 */
function quote(s) {
  const text = String(s);
  const q = text.includes("'") && !text.includes('"') ? '"' : "'";
  const body = text
    .replace(/\\/g, '\\\\')
    .replace(new RegExp(q, 'g'), '\\' + q)
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t');
  return q + body + q;
}

/**
 * Greedy word wrap equivalent to `textwrap.wrap(text, width)` after
 * `re.sub(r'\s+', ' ', text).strip()` — which is what
 * `HelpFormatter._split_lines` does. Words longer than `width` are hard-broken,
 * matching textwrap's default `break_long_words=True`.
 *
 * @param {string} text
 * @param {number} width
 * @returns {string[]} the wrapped lines (empty array for blank input)
 */
function wrapText(text, width) {
  const words = String(text).replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  const lines = [];
  let current = '';
  for (let word of words) {
    // Hard-break any word that cannot fit on a line of its own.
    while (word.length > width) {
      if (current !== '') {
        lines.push(current);
        current = '';
      }
      lines.push(word.slice(0, width));
      word = word.slice(width);
    }
    if (current === '') current = word;
    else if (current.length + 1 + word.length <= width) current += ' ' + word;
    else {
      lines.push(current);
      current = word;
    }
  }
  if (current !== '') lines.push(current);
  return lines;
}

// ---------------------------------------------------------------------------
// Errors
// ---------------------------------------------------------------------------

/**
 * Port of `argparse.ArgumentError`: an error tied to a specific action, whose
 * string form is prefixed with `argument <name>: `.
 */
class ArgumentError extends Error {
  /**
   * @param {Action|null} action the offending action (null for parser-level errors)
   * @param {string} message
   */
  constructor(action, message) {
    const name = action ? getActionName(action) : null;
    super(name === null ? message : `argument ${name}: ${message}`);
    this.name = 'ArgumentError';
    this.argumentName = name;
    this.argparseMessage = message;
  }
}

/**
 * Port of `argparse._get_action_name`. Note the `'/'` join: an action with
 * several option strings is reported as `-h/--help`.
 *
 * @param {Action} action
 * @returns {string|null}
 */
function getActionName(action) {
  if (!action) return null;
  if (action.option_strings.length > 0) return action.option_strings.join('/');
  if (action.metavar != null) return action.metavar;
  if (action.dest != null) return action.dest;
  return null;
}

// ---------------------------------------------------------------------------
// Actions
// ---------------------------------------------------------------------------

/**
 * How many argument strings each action kind consumes. `null` means "exactly
 * one" (CPython's `nargs=None`); `0` means "none".
 */
const NARGS_BY_KIND = {
  store: null,
  store_true: 0,
  store_false: 0,
  store_const: 0,
  count: 0,
  help: 0,
};

/**
 * Whether an action is hidden from usage and help output. Pass `help: false`
 * (or the Python-style SUPPRESS string) to hide an argument.
 *
 * @param {Action} action
 * @returns {boolean}
 */
const isHidden = (action) => action.help === false || action.help === SUPPRESS;

/** A single registered argument. Mirrors `argparse.Action`. */
class Action {
  /**
   * @param {object} spec
   * @param {string[]} spec.option_strings
   * @param {string} spec.dest
   * @param {string} spec.kind one of the keys of {@link NARGS_BY_KIND}
   * @param {((value: string) => unknown)|null} [spec.type]
   * @param {boolean} [spec.required]
   * @param {string|null} [spec.help]
   * @param {string|null} [spec.metavar]
   * @param {unknown} [spec.default]
   * @param {unknown} [spec.const]
   */
  constructor({
    option_strings,
    dest,
    kind,
    type = null,
    required = false,
    help = null,
    metavar = null,
    default: defaultValue,
    const: constValue,
  }) {
    this.option_strings = option_strings;
    this.dest = dest;
    this.kind = kind;
    this.nargs = NARGS_BY_KIND[kind];
    this.type = type;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
    this.const = constValue;

    // Defaults follow CPython: `store_true` defaults to false, and so on.
    if (defaultValue !== undefined) this.default = defaultValue;
    else if (kind === 'store_true') this.default = false;
    else if (kind === 'store_false') this.default = true;
    else if (kind === 'count') this.default = null;
    else this.default = null;
  }

  /** The metavar shown in usage/help for this action. */
  get displayMetavar() {
    return this.metavar ?? this.dest.toUpperCase();
  }

  /**
   * Perform the action. Mirrors `Action.__call__`.
   *
   * @param {ArgumentParser} parser
   * @param {Record<string, unknown>} namespace
   * @param {unknown} values
   */
  call(parser, namespace, values) {
    switch (this.kind) {
      case 'store':
        namespace[this.dest] = values;
        break;
      case 'store_true':
        namespace[this.dest] = true;
        break;
      case 'store_false':
        namespace[this.dest] = false;
        break;
      case 'store_const':
        namespace[this.dest] = this.const;
        break;
      case 'count':
        namespace[this.dest] = (namespace[this.dest] ?? 0) + 1;
        break;
      case 'help':
        parser.print_help();
        parser.exit(0);
        break;
      /* c8 ignore next 2 */
      default:
        throw new Error(`unsupported action: ${this.kind}`);
    }
  }
}

// ---------------------------------------------------------------------------
// Help formatting
// ---------------------------------------------------------------------------

/** Port of the parts of `argparse.HelpFormatter` that we need. */
class HelpFormatter {
  /**
   * @param {string} prog program name shown in usage
   * @param {number} columns assumed terminal width
   */
  constructor(prog, columns) {
    this.prog = prog;
    // CPython: `width = shutil.get_terminal_size().columns - 2`.
    this.width = Math.max(columns - 2, 11);
    this.maxHelpPosition = Math.min(
      MAX_HELP_POSITION,
      Math.max(this.width - 20, INDENT_INCREMENT * 2),
    );
  }

  /**
   * `_format_action_invocation`: `-h, --help` for zero-arg actions,
   * `--a A` (repeated per option string) for value-taking ones.
   *
   * @param {Action} action
   * @returns {string}
   */
  formatInvocation(action) {
    if (action.nargs === 0) return action.option_strings.join(', ');
    const metavar = action.displayMetavar;
    return action.option_strings.map((opt) => `${opt} ${metavar}`).join(', ');
  }

  /**
   * `_format_actions_usage` for a single optional: `[-h]`, `--a A`.
   *
   * @param {Action} action
   * @returns {string}
   */
  formatUsagePart(action) {
    const optionString = action.option_strings[0];
    const part =
      action.nargs === 0 ? optionString : `${optionString} ${action.displayMetavar}`;
    return action.required ? part : `[${part}]`;
  }

  /**
   * The usage line(s), without a trailing newline. Port of `_format_usage`,
   * including the continuation-line wrapping that kicks in once the usage
   * exceeds the available width.
   *
   * @param {Action[]} actions
   * @returns {string}
   */
  formatUsage(actions) {
    const prefix = 'usage: ';
    const prog = this.prog;
    const visible = actions.filter((action) => !isHidden(action));

    const optUsage = visible.map((action) => this.formatUsagePart(action)).join(' ');
    let usage = [prog, optUsage].filter((s) => s !== '').join(' ');

    const textWidth = this.width;
    if (prefix.length + usage.length > textWidth) {
      // Break the usage into wrappable parts: bracketed/parenthesised groups
      // stay intact, everything else splits on whitespace.
      const optParts = optUsage.match(/\(.*?\)+(?=\s|$)|\[.*?\]+(?=\s|$)|\S+/g) ?? [];

      /**
       * @param {string[]} parts
       * @param {string} indent
       * @param {string|null} [linePrefix] set on the first line only
       * @returns {string[]}
       */
      const getLines = (parts, indent, linePrefix = null) => {
        const lines = [];
        let line = [];
        let lineLen = (linePrefix !== null ? linePrefix.length : indent.length) - 1;
        for (const part of parts) {
          if (lineLen + 1 + part.length > textWidth && line.length > 0) {
            lines.push(indent + line.join(' '));
            line = [];
            lineLen = indent.length - 1;
          }
          line.push(part);
          lineLen += 1 + part.length;
        }
        if (line.length > 0) lines.push(indent + line.join(' '));
        if (linePrefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
        return lines;
      };

      let lines;
      if (prefix.length + prog.length <= 0.75 * textWidth) {
        // Short program name: the first group of options follows it.
        const indent = pad(prefix.length + prog.length + 1);
        lines = optParts.length > 0 ? getLines([prog, ...optParts], indent, prefix) : [prog];
      } else {
        // Long program name: it gets a line of its own.
        const indent = pad(prefix.length);
        lines = [prog, ...getLines(optParts, indent)];
      }
      usage = lines.join('\n');
    }

    return prefix + usage;
  }

  /**
   * `_action_max_length`: the longest invocation, plus the section indent.
   *
   * @param {Action[]} actions
   * @returns {number}
   */
  actionMaxLength(actions) {
    let max = 0;
    for (const action of actions) {
      if (isHidden(action)) continue;
      max = Math.max(max, this.formatInvocation(action).length + INDENT_INCREMENT);
    }
    return max;
  }

  /**
   * `_format_action`: one entry of the `options:` section, including the
   * column alignment and help-text wrapping.
   *
   * @param {Action} action
   * @param {number} helpPosition column at which help text starts
   * @returns {string}
   */
  formatAction(action, helpPosition) {
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - INDENT_INCREMENT - 2;
    const invocation = this.formatInvocation(action);

    let header;
    let indentFirst = 0;
    const helpText = action.help ? String(action.help) : '';

    if (!helpText) {
      // No help: the invocation is the whole line.
      header = pad(INDENT_INCREMENT) + invocation + '\n';
    } else if (invocation.length <= actionWidth) {
      // Short invocation: pad it out so help starts at `helpPosition`.
      header = pad(INDENT_INCREMENT) + invocation + pad(actionWidth - invocation.length) + '  ';
      indentFirst = 0;
    } else {
      // Long invocation: help starts on the following line.
      header = pad(INDENT_INCREMENT) + invocation + '\n';
      indentFirst = helpPosition;
    }

    const parts = [header];
    if (helpText.trim() !== '') {
      const lines = wrapText(helpText, helpWidth);
      parts.push(pad(indentFirst) + lines[0] + '\n');
      for (const line of lines.slice(1)) parts.push(pad(helpPosition) + line + '\n');
    } else if (!header.endsWith('\n')) {
      parts.push('\n');
    }
    return parts.join('');
  }

  /**
   * The complete help text, matching `ArgumentParser.format_help()` byte for
   * byte (including the blank-line collapsing and single trailing newline).
   *
   * @param {Action[]} actions
   * @param {{description?: string|null, epilog?: string|null}} [text]
   * @returns {string}
   */
  formatHelp(actions, { description = null, epilog = null } = {}) {
    const parts = [this.formatUsage(actions) + '\n\n'];

    if (description) parts.push(wrapText(description, this.width).join('\n') + '\n\n');

    const visible = actions.filter((action) => !isHidden(action));
    if (visible.length > 0) {
      const helpPosition = Math.min(this.actionMaxLength(visible) + 2, this.maxHelpPosition);
      parts.push('\n', 'options:\n');
      for (const action of visible) parts.push(this.formatAction(action, helpPosition));
      parts.push('\n');
    }

    if (epilog) parts.push('\n' + wrapText(epilog, this.width).join('\n') + '\n\n');

    // `_long_break_matcher.sub('\n\n', ...)` then `.strip('\n') + '\n'`.
    const joined = parts.join('').replace(/\n{3,}/g, '\n\n');
    return joined.replace(/^\n+/, '').replace(/\n+$/, '') + '\n';
  }
}

// ---------------------------------------------------------------------------
// ArgumentParser
// ---------------------------------------------------------------------------

/**
 * A drop-in-ish clone of `argparse.ArgumentParser` for optional arguments.
 *
 * @example
 * const parser = new ArgumentParser();
 * parser.add_argument('--a', { type: String, required: true, help: 'Numbers' });
 * const args = parser.parse_args();   // -> { help: null, a: '1,2,3' }
 */
export class ArgumentParser {
  /**
   * @param {object} [options]
   * @param {string} [options.prog] program name; defaults to `basename(process.argv[1])`
   * @param {string|null} [options.description]
   * @param {string|null} [options.epilog]
   * @param {boolean} [options.add_help] add `-h/--help` (default true)
   * @param {boolean} [options.allow_abbrev] allow long-option prefixes (default true)
   * @param {string} [options.prefix_chars] default `'-'`
   * @param {boolean} [options.exit_on_error] convert ArgumentError into `error()` (default true)
   * @param {number} [options.columns] assumed terminal width (default 80)
   */
  constructor({
    prog,
    description = null,
    epilog = null,
    add_help = true,
    allow_abbrev = true,
    prefix_chars = DEFAULT_PREFIX_CHARS,
    exit_on_error = true,
    columns = DEFAULT_COLUMNS,
  } = {}) {
    // Python uses `basename(sys.argv[0])`; the Node equivalent is argv[1],
    // since argv[0] is the node binary itself.
    this.prog = prog ?? basename(process.argv[1] ?? '');
    this.description = description;
    this.epilog = epilog;
    this.prefix_chars = prefix_chars;
    this.allow_abbrev = allow_abbrev;
    this.exit_on_error = exit_on_error;
    this.columns = columns;

    /** @type {Action[]} */
    this._actions = [];
    /** @type {Map<string, Action>} */
    this._option_string_actions = new Map();
    /** Set when any option string itself looks like a negative number. */
    this._has_negative_number_optionals = false;

    if (add_help) {
      this.add_argument('-h', '--help', {
        action: 'help',
        dest: SUPPRESS, // keeps `help` off the parsed namespace, as in Python
        help: 'show this help message and exit',
      });
    }
  }

  // -- registration --------------------------------------------------------

  /**
   * Register an optional argument.
   *
   * @param {...(string|object)} args one or more flag strings, optionally
   *   followed by an options object:
   *   `{ type, required, help, action, dest, metavar, default, const }`.
   * @returns {Action} the created action
   */
  add_argument(...args) {
    let options = {};
    if (args.length > 0 && typeof args[args.length - 1] === 'object' && args[args.length - 1] !== null) {
      options = /** @type {object} */ (args.pop());
    }
    const flags = /** @type {string[]} */ (args);

    if (flags.length === 0) {
      throw new Error('add_argument() requires at least one option string');
    }
    for (const flag of flags) {
      if (typeof flag !== 'string' || flag.length === 0 || !this.prefix_chars.includes(flag[0])) {
        throw new Error(
          `add_argument(): positional arguments are not supported (got ${quote(String(flag))})`,
        );
      }
    }

    const kind = options.action ?? 'store';
    if (!(kind in NARGS_BY_KIND)) {
      throw new Error(`unsupported action: ${quote(String(kind))}`);
    }

    // dest inference: prefer the first long option ('--foo-bar' -> 'foo_bar').
    const isLong = (flag) => flag.length > 1 && this.prefix_chars.includes(flag[1]);
    let dest = options.dest;
    if (dest == null) {
      const source = flags.find(isLong) ?? flags[0];
      dest = source.replace(new RegExp(`^[${this.prefix_chars}]+`), '').replace(/-/g, '_');
      if (dest === '') throw new Error(`dest is required for options like ${quote(flags[0])}`);
    }

    const action = new Action({
      option_strings: flags,
      dest,
      kind,
      type: options.type ?? null,
      required: Boolean(options.required),
      help: options.help ?? null,
      metavar: options.metavar ?? null,
      default: options.default,
      const: options.const,
    });

    for (const flag of flags) {
      if (this._option_string_actions.has(flag)) {
        throw new Error(`conflicting option string: ${flag}`);
      }
      this._option_string_actions.set(flag, action);
      if (NEGATIVE_NUMBER_MATCHER.test(flag)) this._has_negative_number_optionals = true;
    }
    this._actions.push(action);
    return action;
  }

  // -- output --------------------------------------------------------------

  /** @returns {string} the usage line, with a trailing newline. */
  format_usage() {
    return this._formatter().formatUsage(this._actions) + '\n';
  }

  /** @returns {string} the full help text, with a trailing newline. */
  format_help() {
    return this._formatter()
      .formatHelp(this._actions, { description: this.description, epilog: this.epilog });
  }

  /**
   * @param {(text: string) => unknown} [write] defaults to stdout
   */
  print_usage(write = writeStdout) {
    write(this.format_usage());
  }

  /**
   * @param {(text: string) => unknown} [write] defaults to stdout
   */
  print_help(write = writeStdout) {
    write(this.format_help());
  }

  /**
   * Print usage plus `<prog>: error: <message>` to stderr and exit with 2.
   *
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    this.print_usage(writeStderr);
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  /**
   * @param {number} [status]
   * @param {string} [message] written to stderr when present
   * @returns {never}
   */
  exit(status = 0, message) {
    if (message) writeStderr(message);
    process.exit(status);
    /* c8 ignore next 2 */
    throw new Error('unreachable'); // keeps control-flow analysis honest
  }

  /** @returns {HelpFormatter} */
  _formatter() {
    return new HelpFormatter(this.prog, this.columns);
  }

  // -- parsing -------------------------------------------------------------

  /**
   * Parse `argv`, erroring out on anything left over.
   *
   * @param {string[]} [argv] defaults to `process.argv.slice(2)`
   * @returns {Record<string, unknown>} the populated namespace
   */
  parse_args(argv) {
    const [namespace, extras] = this.parse_known_args(argv);
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }

  /**
   * Parse `argv`, returning the namespace and any unrecognized arguments.
   *
   * @param {string[]} [argv] defaults to `process.argv.slice(2)`
   * @returns {[Record<string, unknown>, string[]]}
   */
  parse_known_args(argv) {
    const argStrings = argv ?? process.argv.slice(2);

    // Seed defaults before parsing, as CPython does. Actions whose dest is
    // suppressed (the built-in --help) never appear on the namespace.
    /** @type {Record<string, unknown>} */
    const namespace = {};
    for (const action of this._actions) {
      if (action.dest === SUPPRESS) continue;
      if (!(action.dest in namespace)) namespace[action.dest] = action.default;
    }

    try {
      return this._parseKnownArgs(argStrings, namespace);
    } catch (err) {
      if (this.exit_on_error && err instanceof ArgumentError) this.error(err.message);
      throw err;
    }
  }

  /**
   * Port of `_parse_known_args`.
   *
   * @param {string[]} argStrings
   * @param {Record<string, unknown>} namespace
   * @returns {[Record<string, unknown>, string[]]}
   */
  _parseKnownArgs(argStrings, namespace) {
    /**
     * Classify every token: 'O' for an option, 'A' for a value, '-' for the
     * end-of-options marker. Everything after the FIRST '--' is forced to 'A'.
     * @type {Map<number, [Action|null, string, string|null, string|null]>}
     */
    const optionStringIndices = new Map();
    const patternParts = [];
    let sawDoubleDash = false;
    for (let i = 0; i < argStrings.length; i++) {
      const argString = argStrings[i];
      if (sawDoubleDash) {
        patternParts.push('A');
      } else if (argString === '--') {
        sawDoubleDash = true;
        patternParts.push('-');
      } else {
        const optionTuple = this._parseOptional(argString);
        if (optionTuple === null) {
          patternParts.push('A');
        } else {
          optionStringIndices.set(i, optionTuple);
          patternParts.push('O');
        }
      }
    }
    const argStringsPattern = patternParts.join('');

    /** @type {string[]} */
    const extras = [];
    const seenActions = new Set();

    const takeAction = (action, argumentStrings) => {
      seenActions.add(action);
      action.call(this, namespace, this._getValues(action, argumentStrings));
    };

    /**
     * Port of `consume_optional`: handles `--opt value`, `--opt=value`, and
     * bundled short options such as `-xvf`.
     *
     * @param {number} startIndex
     * @returns {number} the index just past this option and its arguments
     */
    const consumeOptional = (startIndex) => {
      let [action, optionString, sep, explicitArg] = optionStringIndices.get(startIndex);
      /** @type {[Action, string[]][]} */
      const actionTuples = [];
      let stop;

      for (;;) {
        // An unknown option string: record it as an extra and move on.
        if (action === null) {
          extras.push(argStrings[startIndex]);
          return startIndex + 1;
        }

        if (explicitArg !== null) {
          const argCount = this._matchArgument(action, 'A');
          const chars = this.prefix_chars;

          if (argCount === 0 && !chars.includes(optionString[1]) && explicitArg !== '') {
            // `-xvf`: a zero-arg short option with more short options glued on.
            if (sep || chars.includes(explicitArg[0])) {
              throw new ArgumentError(action, `ignored explicit argument ${quote(explicitArg)}`);
            }
            actionTuples.push([action, []]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            if (this._option_string_actions.has(optionString)) {
              action = this._option_string_actions.get(optionString);
              explicitArg = explicitArg.slice(1);
              if (explicitArg === '') {
                sep = null;
                explicitArg = null;
              } else if (explicitArg[0] === '=') {
                sep = '=';
                explicitArg = explicitArg.slice(1);
              } else {
                sep = '';
              }
            } else {
              extras.push(char + explicitArg);
              stop = startIndex + 1;
              break;
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg]]);
            break;
          } else {
            throw new ArgumentError(action, `ignored explicit argument ${quote(explicitArg)}`);
          }
        } else {
          // No explicit argument: take values from the following tokens.
          const start = startIndex + 1;
          const argCount = this._matchArgument(action, argStringsPattern.slice(start));
          stop = start + argCount;
          actionTuples.push([action, argStrings.slice(start, stop)]);
          break;
        }
      }

      for (const [tupleAction, tupleArgs] of actionTuples) takeAction(tupleAction, tupleArgs);
      return stop;
    };

    /**
     * Port of `consume_positionals`. This parser registers no positionals, so
     * nothing is ever consumed; the function is kept so that the surrounding
     * control flow (and therefore the "unrecognized arguments" behaviour)
     * stays identical to CPython's.
     *
     * @param {number} startIndex
     * @returns {number}
     */
    const consumePositionals = (startIndex) => startIndex;

    // Alternate between positionals and optionals until past the last option.
    let startIndex = 0;
    const optionIndices = [...optionStringIndices.keys()];
    const maxOptionStringIndex = optionIndices.length > 0 ? Math.max(...optionIndices) : -1;

    while (startIndex <= maxOptionStringIndex) {
      const nextOptionStringIndex = Math.min(
        ...optionIndices.filter((index) => index >= startIndex),
      );

      if (startIndex !== nextOptionStringIndex) {
        const positionalsEndIndex = consumePositionals(startIndex);
        if (positionalsEndIndex > startIndex) {
          startIndex = positionalsEndIndex;
          continue;
        }
        startIndex = positionalsEndIndex;
      }

      if (!optionStringIndices.has(startIndex)) {
        extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
        startIndex = nextOptionStringIndex;
      }

      startIndex = consumeOptional(startIndex);
    }

    const stopIndex = consumePositionals(startIndex);
    extras.push(...argStrings.slice(stopIndex));

    // Required-argument checking happens here, i.e. BEFORE parse_args()
    // reports unrecognized arguments.
    const requiredActions = [];
    for (const action of this._actions) {
      if (!seenActions.has(action) && action.required) {
        requiredActions.push(getActionName(action));
      }
    }
    if (requiredActions.length > 0) {
      this.error(`the following arguments are required: ${requiredActions.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * Port of `_parse_optional`. Returns `null` when the token is a value, or a
   * `[action, optionString, sep, explicitArg]` tuple when it is (or looks
   * like) an option. `action` is `null` for an unrecognized option string.
   *
   * @param {string} argString
   * @returns {[Action|null, string, string|null, string|null]|null}
   */
  _parseOptional(argString) {
    // Empty string, or no prefix char: it is a value.
    if (argString === '') return null;
    if (!this.prefix_chars.includes(argString[0])) return null;

    // Exact match against a known option string.
    if (this._option_string_actions.has(argString)) {
      return [this._option_string_actions.get(argString), argString, null, null];
    }

    // A bare '-' is a value.
    if (argString.length === 1) return null;

    // '--opt=value' where '--opt' is known.
    const eq = argString.indexOf('=');
    if (eq !== -1) {
      const optionString = argString.slice(0, eq);
      const explicitArg = argString.slice(eq + 1);
      if (this._option_string_actions.has(optionString)) {
        return [this._option_string_actions.get(optionString), optionString, '=', explicitArg];
      }
    }

    // Prefix/abbreviation matching.
    const optionTuples = this._getOptionTuples(argString);
    if (optionTuples.length > 1) {
      const matches = optionTuples.map(([, optionString]) => optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    } else if (optionTuples.length === 1) {
      return optionTuples[0];
    }

    // Looks like a negative number, and no option string does: it is a value.
    if (NEGATIVE_NUMBER_MATCHER.test(argString) && !this._has_negative_number_optionals) {
      return null;
    }

    // Contains a space: it is a value.
    if (argString.includes(' ')) return null;

    // An option string, but not one this parser knows about.
    return [null, argString, null, null];
  }

  /**
   * Port of `_get_option_tuples`: candidate interpretations of an abbreviated
   * or glued-together option string.
   *
   * @param {string} optionString
   * @returns {[Action, string, string|null, string|null][]}
   */
  _getOptionTuples(optionString) {
    /** @type {[Action, string, string|null, string|null][]} */
    const result = [];
    const chars = this.prefix_chars;

    if (chars.includes(optionString[0]) && chars.includes(optionString[1])) {
      // Long option: only ever split at '='.
      if (!this.allow_abbrev) return result;
      const eq = optionString.indexOf('=');
      const optionPrefix = eq === -1 ? optionString : optionString.slice(0, eq);
      const sep = eq === -1 ? null : '=';
      const explicitArg = eq === -1 ? null : optionString.slice(eq + 1);
      for (const [known, action] of this._option_string_actions) {
        if (known.startsWith(optionPrefix)) result.push([action, known, sep, explicitArg]);
      }
    } else {
      // Short option: its argument may be glued directly to it.
      const optionPrefix = optionString;
      const shortOptionPrefix = optionString.slice(0, 2);
      const shortExplicitArg = optionString.slice(2);
      for (const [known, action] of this._option_string_actions) {
        if (known === shortOptionPrefix) result.push([action, known, '', shortExplicitArg]);
        else if (known.startsWith(optionPrefix)) result.push([action, known, null, null]);
      }
    }
    return result;
  }

  /**
   * Port of `_match_argument`: how many of the following tokens this action
   * takes, given the classification pattern of the remaining tokens.
   *
   * @param {Action} action
   * @param {string} argStringsPattern
   * @returns {number}
   */
  _matchArgument(action, argStringsPattern) {
    const match = new RegExp('^' + this._nargsPattern(action)).exec(argStringsPattern);
    if (match === null) throw new ArgumentError(action, 'expected one argument');
    return match[1].length;
  }

  /**
   * Port of `_get_nargs_pattern`. `'--'` (pattern char `-`) is never allowed
   * to satisfy an optional's arguments, which is why `-*` is stripped.
   *
   * @param {Action} action
   * @returns {string}
   */
  _nargsPattern(action) {
    let pattern;
    if (action.nargs === null) pattern = '(-*A-*)';
    else pattern = '(-*' + Array(action.nargs).fill('A').join('-*') + '-*)';
    if (action.option_strings.length > 0) {
      pattern = pattern.replace(/-\*/g, '').replace(/-/g, '');
    }
    return pattern;
  }

  /**
   * Port of `_get_values` + `_get_value` for the nargs we support.
   *
   * @param {Action} action
   * @param {string[]} argStrings
   * @returns {unknown}
   */
  _getValues(action, argStrings) {
    if (action.nargs === 0) return undefined;
    const argString = argStrings[0];
    if (action.type == null || action.type === String) return argString;
    try {
      return action.type(argString);
    } catch {
      const typeName = action.type.name || 'value';
      throw new ArgumentError(action, `invalid ${typeName} value: ${quote(argString)}`);
    }
  }
}

